UI.EDITMODE_LAYOUT_NAME = 'Jiberish SPEC-01'

function UI:ApplyDefaultEditMode(quiet)
	local Kit = UI.Kit
	local function Fail(text)
		if not quiet then
			Kit:Play('error')
			Kit:Toast({title = 'Edit Mode layout', text = text, tone = 'warning'})
		end
		return false
	end
	if InCombatLockdown() then return Fail('Not in combat: try again after the fight.') end
	local api = C_EditMode
	if not (api and api.ConvertStringToLayoutInfo and api.GetLayouts and api.SaveLayouts and api.SetActiveLayout) then
		return Fail('This client has no Edit Mode layouts.')
	end
	local ok, info = pcall(api.ConvertStringToLayoutInfo, UI.DEFAULT_EDITMODE)
	if not ok or type(info) ~= 'table' then return Fail('This client can\'t read the layout (it was made on Forever).') end
	local saved = api.GetLayouts()
	if type(saved) ~= 'table' or type(saved.layouts) ~= 'table' then return Fail('Edit Mode\'s layouts could not be read.') end
	local name = UI.EDITMODE_LAYOUT_NAME
	info.layoutName = name
	info.layoutType = Enum and Enum.EditModeLayoutType and Enum.EditModeLayoutType.Account or info.layoutType or 0
	-- Replace a layout of the same name, else add one (if there is room).
	local index, accounts = nil, 0
	for position, layout in ipairs(saved.layouts) do
		if layout.layoutName == name then index = position end
		if layout.layoutType == info.layoutType then accounts = accounts + 1 end
	end
	if index then
		saved.layouts[index] = info
	else
		local most = Constants and Constants.EditModeConsts and Constants.EditModeConsts.EditModeMaxLayoutsPerType or 5
		if accounts >= most then return Fail('Edit Mode already holds as many layouts as it allows. Delete one there first.') end
		saved.layouts[#saved.layouts + 1] = info
		index = #saved.layouts
	end
	-- The active index counts the game's preset layouts (Modern, Classic) first.
	local presets = 2
	local manager = EditModePresetLayoutManager
	if manager and manager.GetCopyOfPresetLayouts then
		local okPresets, list = pcall(manager.GetCopyOfPresetLayouts, manager)
		if okPresets and type(list) == 'table' then presets = #list end
	end
	saved.activeLayout = presets + index
	if not pcall(api.SaveLayouts, saved) then return Fail('Edit Mode refused the layout.') end
	pcall(api.SetActiveLayout, presets + index)
	if not quiet then
		Kit:Play('latch-down')
		Kit:AlertDialog({title = 'Edit Mode layout', confirm = 'Reload', reload = true,
			text = 'The '..name..' layout is saved and active in Blizzard\'s Edit Mode. Reload so every Blizzard frame takes it up.'})
	end
	return true
end
